SELECT 576, '연결 장애 상황집(3): 이름·TLS·HTTP — 오류 번호, 리다이렉트 루프, 502 와 504, 낡은 hosts, 만료 인증서', '"웹이 안 된다"는 신고를 받았을 때 이름 해석·TLS·HTTP 중 어디가 원인인지 가려내는 상황집입니다. curl 오류 번호, 리다이렉트 루프, 프록시의 502 와 504, 검색 도메인 때문에 느린 이름 해석, 인증서 만료일을 현장 출력에서 읽고, 서버의 낡은 /etc/hosts 항목은 직접 고칩니다.', 'linux', '네트워크'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest_set WHERE id = 576);
UPDATE quest_set SET display_order = 836, unit_id = (SELECT id FROM unit WHERE id = 43), icon = '🌐' WHERE id = 576;

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 576, 1, 'curl 오류 번호로 층 나누기', '`/tmp/curl_errs.log` 는 같은 서비스에 접속하며 서로 다른 시점에 본 curl 오류들입니다. 오류 번호(괄호 안 숫자)마다 원인이 있는 층이 다릅니다. 아래 두 오류의 **번호만** 저장하세요.
- `/tmp/dns_code.txt` : 이름을 해석하지 못한 오류
- `/tmp/tls_code.txt` : 인증서 문제로 실패한 오류', '오류 문구에서 이름 해석이나 인증서를 말하는 줄을 찾고, 그 줄의 괄호 안 번호를 뽑으세요.', 'cat /tmp/curl_errs.log
grep ''resolve host'' /tmp/curl_errs.log | grep -o ''([0-9]*)'' | tr -d ''()'' > /tmp/dns_code.txt
grep ''certificate'' /tmp/curl_errs.log | grep -o ''([0-9]*)'' | tr -d ''()'' > /tmp/tls_code.txt
cat /tmp/dns_code.txt /tmp/tls_code.txt

# 6 은 이름 해석 실패, 60 은 인증서 검증 실패, 7 은 연결 거부, 28 은 시간 초과, 35 는 핸드셰이크 중 끊김이다. 번호만 봐도 어느 층을 볼지 정해진다', '["sh", "-c", "rm -f /tmp/*.txt /tmp/*.log\\ngrep -v ''example.com'' /etc/hosts > /tmp/hosts.base; cat /tmp/hosts.base > /etc/hosts; rm -f /tmp/hosts.base\\nprintf ''%s\\\\n'' ''192.0.2.99 old-api.example.com'' ''192.0.2.77 keep.example.com'' >> /etc/hosts\\ncat > /tmp/curl_errs.log <<''EOF''\\ncurl: (6) Could not resolve host: api.example.com\\ncurl: (7) Failed to connect to api.example.com port 443 after 3 ms: Connection refused\\ncurl: (28) Operation timed out after 10001 milliseconds with 0 bytes received\\ncurl: (35) OpenSSL SSL_connect: Connection reset by peer in connection to api.example.com:443\\ncurl: (60) SSL certificate problem: certificate has expired\\nEOF\\ncat > /tmp/loop.log <<''EOF''\\nHTTP/1.1 301 Moved Permanently\\nLocation: https://shop.example.com/\\nHTTP/1.1 301 Moved Permanently\\nLocation: http://shop.example.com/\\nHTTP/1.1 301 Moved Permanently\\nLocation: https://shop.example.com/\\nHTTP/1.1 301 Moved Permanently\\nLocation: http://shop.example.com/\\ncurl: (47) Maximum (3) redirects followed\\nEOF\\ncat > /tmp/proxy_access.log <<''EOF''\\n192.0.2.50 \\"GET /a HTTP/1.1\\" 200 12ms\\n192.0.2.50 \\"GET /b HTTP/1.1\\" 502 1ms\\n192.0.2.51 \\"GET /c HTTP/1.1\\" 504 60001ms\\n192.0.2.52 \\"GET /d HTTP/1.1\\" 502 2ms\\n192.0.2.53 \\"GET /e HTTP/1.1\\" 200 30ms\\n192.0.2.54 \\"GET /f HTTP/1.1\\" 504 60002ms\\n192.0.2.55 \\"GET /g HTTP/1.1\\" 504 60000ms\\nEOF\\ncat > /tmp/dns_try.log <<''EOF''\\nquery www.example.com.corp.example.com -> NXDOMAIN\\nquery www.example.com.lab.example.com -> NXDOMAIN\\nquery www.example.com -> NOERROR 192.0.2.10\\nEOF\\ncat > /tmp/cert.log <<''EOF''\\nsubject=CN = api.example.com\\nnotBefore=Jan  5 00:00:00 2025 GMT\\nnotAfter=Jan  5 00:00:00 2026 GMT\\nEOF\\ntrue"]', '["sh", "-c", "( [ \\"$(cat /tmp/dns_code.txt)\\" = 6 ] ) && ( [ \\"$(cat /tmp/tls_code.txt)\\" = 60 ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "이름 해석 오류가 6 이다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/dns_code.txt)\\" = 6 ]"]}, {"label": "인증서 오류가 60 이다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/tls_code.txt)\\" = 60 ]"]}]', '[{"title": "curl 종료 코드", "url": "https://curl.se/libcurl/c/libcurl-errors.html"}, {"title": "MDN HTTP 상태 코드", "url": "https://developer.mozilla.org/ko/docs/Web/HTTP/Status"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 576 AND order_index = 1);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 576, 2, '리다이렉트가 도는 횟수', '`/tmp/loop.log` 는 `curl -sSIL --max-redirs 3 http://shop.example.com/` 의 응답 헤더 모음입니다. 요청이 `http` 와 `https` 사이를 계속 오가다 curl 이 중단했습니다. **`301` 응답이 몇 번** 나왔는지 숫자만 `/tmp/redirects.txt` 에 저장하세요.', '상태 줄에 특정 숫자가 들어간 줄의 수를 세면 됩니다.', 'cat /tmp/loop.log
grep -c ''^HTTP/1.1 301'' /tmp/loop.log > /tmp/redirects.txt
cat /tmp/redirects.txt

# 4 번. 앞단(로드밸런서)이 http 를 https 로 보내는데 뒤 서버가 https 요청을 다시 http 로 돌려보내는 식의 설정 충돌이 흔한 원인이다. 어느 쪽이 스킴을 바꾸는지 각각 curl -I 로 확인한다', '["sh", "-c", "rm -f /tmp/*.txt /tmp/*.log\\ngrep -v ''example.com'' /etc/hosts > /tmp/hosts.base; cat /tmp/hosts.base > /etc/hosts; rm -f /tmp/hosts.base\\nprintf ''%s\\\\n'' ''192.0.2.99 old-api.example.com'' ''192.0.2.77 keep.example.com'' >> /etc/hosts\\ncat > /tmp/curl_errs.log <<''EOF''\\ncurl: (6) Could not resolve host: api.example.com\\ncurl: (7) Failed to connect to api.example.com port 443 after 3 ms: Connection refused\\ncurl: (28) Operation timed out after 10001 milliseconds with 0 bytes received\\ncurl: (35) OpenSSL SSL_connect: Connection reset by peer in connection to api.example.com:443\\ncurl: (60) SSL certificate problem: certificate has expired\\nEOF\\ncat > /tmp/loop.log <<''EOF''\\nHTTP/1.1 301 Moved Permanently\\nLocation: https://shop.example.com/\\nHTTP/1.1 301 Moved Permanently\\nLocation: http://shop.example.com/\\nHTTP/1.1 301 Moved Permanently\\nLocation: https://shop.example.com/\\nHTTP/1.1 301 Moved Permanently\\nLocation: http://shop.example.com/\\ncurl: (47) Maximum (3) redirects followed\\nEOF\\ncat > /tmp/proxy_access.log <<''EOF''\\n192.0.2.50 \\"GET /a HTTP/1.1\\" 200 12ms\\n192.0.2.50 \\"GET /b HTTP/1.1\\" 502 1ms\\n192.0.2.51 \\"GET /c HTTP/1.1\\" 504 60001ms\\n192.0.2.52 \\"GET /d HTTP/1.1\\" 502 2ms\\n192.0.2.53 \\"GET /e HTTP/1.1\\" 200 30ms\\n192.0.2.54 \\"GET /f HTTP/1.1\\" 504 60002ms\\n192.0.2.55 \\"GET /g HTTP/1.1\\" 504 60000ms\\nEOF\\ncat > /tmp/dns_try.log <<''EOF''\\nquery www.example.com.corp.example.com -> NXDOMAIN\\nquery www.example.com.lab.example.com -> NXDOMAIN\\nquery www.example.com -> NOERROR 192.0.2.10\\nEOF\\ncat > /tmp/cert.log <<''EOF''\\nsubject=CN = api.example.com\\nnotBefore=Jan  5 00:00:00 2025 GMT\\nnotAfter=Jan  5 00:00:00 2026 GMT\\nEOF\\ntrue"]', '["sh", "-c", "( [ \\"$(cat /tmp/redirects.txt)\\" = 4 ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "4 이다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/redirects.txt)\\" = 4 ]"]}]', '[{"title": "curl 종료 코드", "url": "https://curl.se/libcurl/c/libcurl-errors.html"}, {"title": "MDN HTTP 상태 코드", "url": "https://developer.mozilla.org/ko/docs/Web/HTTP/Status"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 576 AND order_index = 2);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 576, 3, '502 와 504 세어 보기', '`/tmp/proxy_access.log` 는 리버스 프록시의 접근 로그(요청, 상태 코드, 처리 시간)입니다. 아래 두 값을 저장하세요. (숫자만)
- `/tmp/c502.txt` : 상태 코드 **502** 의 개수
- `/tmp/c504.txt` : 상태 코드 **504** 의 개수', '상태 코드와 처리 시간이 섞이지 않게 칸 단위로 비교해 보세요.', 'cat /tmp/proxy_access.log
awk ''$NF != "" {print $(NF-1)}'' /tmp/proxy_access.log | grep -c ''^502$'' > /tmp/c502.txt
awk ''{print $(NF-1)}'' /tmp/proxy_access.log | grep -c ''^504$'' > /tmp/c504.txt
cat /tmp/c502.txt /tmp/c504.txt

# 502 는 처리 시간이 1~2ms 로 매우 짧다(업스트림이 즉시 거부·연결 실패). 504 는 60 초 근처다(업스트림이 응답하지 않아 프록시가 제한 시간까지 기다림)', '["sh", "-c", "rm -f /tmp/*.txt /tmp/*.log\\ngrep -v ''example.com'' /etc/hosts > /tmp/hosts.base; cat /tmp/hosts.base > /etc/hosts; rm -f /tmp/hosts.base\\nprintf ''%s\\\\n'' ''192.0.2.99 old-api.example.com'' ''192.0.2.77 keep.example.com'' >> /etc/hosts\\ncat > /tmp/curl_errs.log <<''EOF''\\ncurl: (6) Could not resolve host: api.example.com\\ncurl: (7) Failed to connect to api.example.com port 443 after 3 ms: Connection refused\\ncurl: (28) Operation timed out after 10001 milliseconds with 0 bytes received\\ncurl: (35) OpenSSL SSL_connect: Connection reset by peer in connection to api.example.com:443\\ncurl: (60) SSL certificate problem: certificate has expired\\nEOF\\ncat > /tmp/loop.log <<''EOF''\\nHTTP/1.1 301 Moved Permanently\\nLocation: https://shop.example.com/\\nHTTP/1.1 301 Moved Permanently\\nLocation: http://shop.example.com/\\nHTTP/1.1 301 Moved Permanently\\nLocation: https://shop.example.com/\\nHTTP/1.1 301 Moved Permanently\\nLocation: http://shop.example.com/\\ncurl: (47) Maximum (3) redirects followed\\nEOF\\ncat > /tmp/proxy_access.log <<''EOF''\\n192.0.2.50 \\"GET /a HTTP/1.1\\" 200 12ms\\n192.0.2.50 \\"GET /b HTTP/1.1\\" 502 1ms\\n192.0.2.51 \\"GET /c HTTP/1.1\\" 504 60001ms\\n192.0.2.52 \\"GET /d HTTP/1.1\\" 502 2ms\\n192.0.2.53 \\"GET /e HTTP/1.1\\" 200 30ms\\n192.0.2.54 \\"GET /f HTTP/1.1\\" 504 60002ms\\n192.0.2.55 \\"GET /g HTTP/1.1\\" 504 60000ms\\nEOF\\ncat > /tmp/dns_try.log <<''EOF''\\nquery www.example.com.corp.example.com -> NXDOMAIN\\nquery www.example.com.lab.example.com -> NXDOMAIN\\nquery www.example.com -> NOERROR 192.0.2.10\\nEOF\\ncat > /tmp/cert.log <<''EOF''\\nsubject=CN = api.example.com\\nnotBefore=Jan  5 00:00:00 2025 GMT\\nnotAfter=Jan  5 00:00:00 2026 GMT\\nEOF\\ntrue"]', '["sh", "-c", "( [ \\"$(cat /tmp/c502.txt)\\" = 2 ] ) && ( [ \\"$(cat /tmp/c504.txt)\\" = 3 ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "502 가 2개다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/c502.txt)\\" = 2 ]"]}, {"label": "504 가 3개다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/c504.txt)\\" = 3 ]"]}]', '[{"title": "curl 종료 코드", "url": "https://curl.se/libcurl/c/libcurl-errors.html"}, {"title": "MDN HTTP 상태 코드", "url": "https://developer.mozilla.org/ko/docs/Web/HTTP/Status"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 576 AND order_index = 3);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 576, 4, '낡은 hosts 항목 지우기', '이 서버의 `/etc/hosts` 에 옛 주소를 가리키는 낡은 항목 `old-api.example.com` 이 남아 있어, DNS 가 바뀌어도 이 서버에서만 옛 주소로 접속됩니다. **그 항목만 지우세요.** 같은 파일의 `keep.example.com` 항목은 **그대로 남아야** 합니다.', '`/etc/hosts` 는 컨테이너가 관리하는 파일이라 `sed -i` 가 실패할 수 있습니다.', 'getent hosts old-api.example.com
grep -v ''old-api.example.com'' /etc/hosts > /tmp/hosts.new
cat /tmp/hosts.new > /etc/hosts
rm -f /tmp/hosts.new
getent hosts keep.example.com

# hosts 는 DNS 보다 먼저 보므로 낡은 항목이 남으면 DNS 를 고쳐도 이 서버만 계속 옛 주소로 간다. 지울 때는 다른 항목이 함께 사라지지 않게 한다', '["sh", "-c", "rm -f /tmp/*.txt /tmp/*.log\\ngrep -v ''example.com'' /etc/hosts > /tmp/hosts.base; cat /tmp/hosts.base > /etc/hosts; rm -f /tmp/hosts.base\\nprintf ''%s\\\\n'' ''192.0.2.99 old-api.example.com'' ''192.0.2.77 keep.example.com'' >> /etc/hosts\\ncat > /tmp/curl_errs.log <<''EOF''\\ncurl: (6) Could not resolve host: api.example.com\\ncurl: (7) Failed to connect to api.example.com port 443 after 3 ms: Connection refused\\ncurl: (28) Operation timed out after 10001 milliseconds with 0 bytes received\\ncurl: (35) OpenSSL SSL_connect: Connection reset by peer in connection to api.example.com:443\\ncurl: (60) SSL certificate problem: certificate has expired\\nEOF\\ncat > /tmp/loop.log <<''EOF''\\nHTTP/1.1 301 Moved Permanently\\nLocation: https://shop.example.com/\\nHTTP/1.1 301 Moved Permanently\\nLocation: http://shop.example.com/\\nHTTP/1.1 301 Moved Permanently\\nLocation: https://shop.example.com/\\nHTTP/1.1 301 Moved Permanently\\nLocation: http://shop.example.com/\\ncurl: (47) Maximum (3) redirects followed\\nEOF\\ncat > /tmp/proxy_access.log <<''EOF''\\n192.0.2.50 \\"GET /a HTTP/1.1\\" 200 12ms\\n192.0.2.50 \\"GET /b HTTP/1.1\\" 502 1ms\\n192.0.2.51 \\"GET /c HTTP/1.1\\" 504 60001ms\\n192.0.2.52 \\"GET /d HTTP/1.1\\" 502 2ms\\n192.0.2.53 \\"GET /e HTTP/1.1\\" 200 30ms\\n192.0.2.54 \\"GET /f HTTP/1.1\\" 504 60002ms\\n192.0.2.55 \\"GET /g HTTP/1.1\\" 504 60000ms\\nEOF\\ncat > /tmp/dns_try.log <<''EOF''\\nquery www.example.com.corp.example.com -> NXDOMAIN\\nquery www.example.com.lab.example.com -> NXDOMAIN\\nquery www.example.com -> NOERROR 192.0.2.10\\nEOF\\ncat > /tmp/cert.log <<''EOF''\\nsubject=CN = api.example.com\\nnotBefore=Jan  5 00:00:00 2025 GMT\\nnotAfter=Jan  5 00:00:00 2026 GMT\\nEOF\\ntrue"]', '["sh", "-c", "( ! grep -v \\"^[[:space:]]*#\\" /etc/hosts | grep -q \\"old-api\\\\.example\\\\.com\\" ) && ( grep -Eq \\"^192\\\\.0\\\\.2\\\\.77[[:space:]]+keep\\\\.example\\\\.com([[:space:]]|$)\\" /etc/hosts )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "낡은 항목이 없다(주석 처리도 인정)", "cmd": ["sh", "-c", "! grep -v \\"^[[:space:]]*#\\" /etc/hosts | grep -q \\"old-api\\\\.example\\\\.com\\""]}, {"label": "keep 항목이 남아 있다", "cmd": ["sh", "-c", "grep -Eq \\"^192\\\\.0\\\\.2\\\\.77[[:space:]]+keep\\\\.example\\\\.com([[:space:]]|$)\\" /etc/hosts"]}]', '[{"title": "curl 종료 코드", "url": "https://curl.se/libcurl/c/libcurl-errors.html"}, {"title": "MDN HTTP 상태 코드", "url": "https://developer.mozilla.org/ko/docs/Web/HTTP/Status"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 576 AND order_index = 4);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 576, 5, 'search 도메인 때문에 느린 해석', '`/tmp/dns_try.log` 는 `ndots:5` 로 설정된 컨테이너(쿠버네티스 파드 등)에서 `www.example.com` 을 찾을 때 리졸버가 실제로 시도한 질의 순서입니다. 이름의 점이 `ndots` 보다 적으면 검색 도메인을 먼저 붙여 시도하기 때문에 **실패하는 질의가 먼저** 나갑니다. 성공하기 전에 **실패한 질의가 몇 번**이었는지 숫자만 `/tmp/failed.txt` 에 저장하세요.', '각 줄 끝의 결과를 보세요. 성공 줄은 제외하고 이름이 없다는 결과의 줄을 세면 됩니다.', 'cat /tmp/dns_try.log
grep -c NXDOMAIN /tmp/dns_try.log > /tmp/failed.txt
cat /tmp/failed.txt

# 2 번. 이름이 끝에 점이 있는 완전한 이름(www.example.com.)이면 검색 도메인을 붙이지 않는다. 질의가 느리면 /etc/resolv.conf 의 options 줄(ndots)과 search 를 확인한다', '["sh", "-c", "rm -f /tmp/*.txt /tmp/*.log\\ngrep -v ''example.com'' /etc/hosts > /tmp/hosts.base; cat /tmp/hosts.base > /etc/hosts; rm -f /tmp/hosts.base\\nprintf ''%s\\\\n'' ''192.0.2.99 old-api.example.com'' ''192.0.2.77 keep.example.com'' >> /etc/hosts\\ncat > /tmp/curl_errs.log <<''EOF''\\ncurl: (6) Could not resolve host: api.example.com\\ncurl: (7) Failed to connect to api.example.com port 443 after 3 ms: Connection refused\\ncurl: (28) Operation timed out after 10001 milliseconds with 0 bytes received\\ncurl: (35) OpenSSL SSL_connect: Connection reset by peer in connection to api.example.com:443\\ncurl: (60) SSL certificate problem: certificate has expired\\nEOF\\ncat > /tmp/loop.log <<''EOF''\\nHTTP/1.1 301 Moved Permanently\\nLocation: https://shop.example.com/\\nHTTP/1.1 301 Moved Permanently\\nLocation: http://shop.example.com/\\nHTTP/1.1 301 Moved Permanently\\nLocation: https://shop.example.com/\\nHTTP/1.1 301 Moved Permanently\\nLocation: http://shop.example.com/\\ncurl: (47) Maximum (3) redirects followed\\nEOF\\ncat > /tmp/proxy_access.log <<''EOF''\\n192.0.2.50 \\"GET /a HTTP/1.1\\" 200 12ms\\n192.0.2.50 \\"GET /b HTTP/1.1\\" 502 1ms\\n192.0.2.51 \\"GET /c HTTP/1.1\\" 504 60001ms\\n192.0.2.52 \\"GET /d HTTP/1.1\\" 502 2ms\\n192.0.2.53 \\"GET /e HTTP/1.1\\" 200 30ms\\n192.0.2.54 \\"GET /f HTTP/1.1\\" 504 60002ms\\n192.0.2.55 \\"GET /g HTTP/1.1\\" 504 60000ms\\nEOF\\ncat > /tmp/dns_try.log <<''EOF''\\nquery www.example.com.corp.example.com -> NXDOMAIN\\nquery www.example.com.lab.example.com -> NXDOMAIN\\nquery www.example.com -> NOERROR 192.0.2.10\\nEOF\\ncat > /tmp/cert.log <<''EOF''\\nsubject=CN = api.example.com\\nnotBefore=Jan  5 00:00:00 2025 GMT\\nnotAfter=Jan  5 00:00:00 2026 GMT\\nEOF\\ntrue"]', '["sh", "-c", "( [ \\"$(cat /tmp/failed.txt)\\" = 2 ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "2 이다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/failed.txt)\\" = 2 ]"]}]', '[{"title": "curl 종료 코드", "url": "https://curl.se/libcurl/c/libcurl-errors.html"}, {"title": "MDN HTTP 상태 코드", "url": "https://developer.mozilla.org/ko/docs/Web/HTTP/Status"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 576 AND order_index = 5);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 576, 6, '인증서가 만료된 지 며칠', '`/tmp/cert.log` 는 접속이 안 되는 서비스의 인증서 정보입니다. 오늘 0시(UTC)가 **2026-11-20** 이라고 할 때, 인증서의 `notAfter`(만료일)로부터 **며칠이 지났는지** 숫자만 `/tmp/expired_days.txt` 에 저장하세요.', '`date -d` 로 날짜를 초 단위 시각으로 바꿀 수 있습니다. 초 단위 시각의 차이를 일 단위로 바꿔 보세요.', 'cat /tmp/cert.log
END=$(grep notAfter /tmp/cert.log | cut -d= -f2)
A=$(date -u -d "$END" +%s)
B=$(date -u -d ''2026-11-20 00:00:00'' +%s)
echo $(( (B - A) / 86400 )) > /tmp/expired_days.txt
cat /tmp/expired_days.txt

# 319 일. 인증서 만료는 갑자기 오는 흔한 장애다. 만료일은 openssl x509 -noout -enddate 로 확인하고 미리 알림을 걸어 둔다', '["sh", "-c", "rm -f /tmp/*.txt /tmp/*.log\\ngrep -v ''example.com'' /etc/hosts > /tmp/hosts.base; cat /tmp/hosts.base > /etc/hosts; rm -f /tmp/hosts.base\\nprintf ''%s\\\\n'' ''192.0.2.99 old-api.example.com'' ''192.0.2.77 keep.example.com'' >> /etc/hosts\\ncat > /tmp/curl_errs.log <<''EOF''\\ncurl: (6) Could not resolve host: api.example.com\\ncurl: (7) Failed to connect to api.example.com port 443 after 3 ms: Connection refused\\ncurl: (28) Operation timed out after 10001 milliseconds with 0 bytes received\\ncurl: (35) OpenSSL SSL_connect: Connection reset by peer in connection to api.example.com:443\\ncurl: (60) SSL certificate problem: certificate has expired\\nEOF\\ncat > /tmp/loop.log <<''EOF''\\nHTTP/1.1 301 Moved Permanently\\nLocation: https://shop.example.com/\\nHTTP/1.1 301 Moved Permanently\\nLocation: http://shop.example.com/\\nHTTP/1.1 301 Moved Permanently\\nLocation: https://shop.example.com/\\nHTTP/1.1 301 Moved Permanently\\nLocation: http://shop.example.com/\\ncurl: (47) Maximum (3) redirects followed\\nEOF\\ncat > /tmp/proxy_access.log <<''EOF''\\n192.0.2.50 \\"GET /a HTTP/1.1\\" 200 12ms\\n192.0.2.50 \\"GET /b HTTP/1.1\\" 502 1ms\\n192.0.2.51 \\"GET /c HTTP/1.1\\" 504 60001ms\\n192.0.2.52 \\"GET /d HTTP/1.1\\" 502 2ms\\n192.0.2.53 \\"GET /e HTTP/1.1\\" 200 30ms\\n192.0.2.54 \\"GET /f HTTP/1.1\\" 504 60002ms\\n192.0.2.55 \\"GET /g HTTP/1.1\\" 504 60000ms\\nEOF\\ncat > /tmp/dns_try.log <<''EOF''\\nquery www.example.com.corp.example.com -> NXDOMAIN\\nquery www.example.com.lab.example.com -> NXDOMAIN\\nquery www.example.com -> NOERROR 192.0.2.10\\nEOF\\ncat > /tmp/cert.log <<''EOF''\\nsubject=CN = api.example.com\\nnotBefore=Jan  5 00:00:00 2025 GMT\\nnotAfter=Jan  5 00:00:00 2026 GMT\\nEOF\\ntrue"]', '["sh", "-c", "( [ \\"$(cat /tmp/expired_days.txt)\\" = 319 ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "319 일이다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/expired_days.txt)\\" = 319 ]"]}]', '[{"title": "curl 종료 코드", "url": "https://curl.se/libcurl/c/libcurl-errors.html"}, {"title": "MDN HTTP 상태 코드", "url": "https://developer.mozilla.org/ko/docs/Web/HTTP/Status"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 576 AND order_index = 6);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 576, 7, '502 와 504 의 차이', '리버스 프록시에서 `502 Bad Gateway` 는 처리 시간이 1~2ms 로 아주 짧고, `504 Gateway Timeout` 은 항상 60초 가까이 걸립니다. 이 차이에서 알 수 있는 것으로 가장 알맞은 것은?', '프록시가 업스트림에서 무엇을 받았는지(또는 받지 못했는지) 생각해 보세요.', NULL, NULL, '[]', 'choice', '["502 는 클라이언트 요청 형식이 잘못되어서이고, 504 는 프록시 설정의 문법 오류 때문이다", "둘 다 업스트림이 아니라 클라이언트의 네트워크 문제여서 업스트림은 볼 필요가 없다", "502 는 업스트림 응답을 못 받아 바로 실패한 것이고, 504 는 기다리다 시간이 초과된 것이다", "502 는 인증서 검증 실패이고, 504 는 DNS 이름 해석 실패이다"]', 2, '502 는 프록시가 업스트림에서 유효한 응답을 얻지 못했을 때(연결 거부·잘못된 응답)로 빠르게 실패합니다. 504 는 업스트림이 제한 시간 안에 응답하지 않을 때라 보통 타임아웃 값 근처의 시간이 걸립니다. 둘 다 업스트림 쪽 원인을 먼저 봐야 합니다.', NULL, NULL, NULL, NULL
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 576 AND order_index = 7);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 576, 8, 'IP 주소로 접속하면 인증서 오류', '`https://api.example.com/` 은 잘 열리는데 같은 서버를 IP 주소(`https://192.0.2.10/`)로 열면 인증서 이름 불일치 오류가 납니다. 가장 알맞은 이유는?', '인증서가 무엇에 대해 발급되었는지 생각해 보세요.', NULL, NULL, '[]', 'choice', '["인증서는 IP 로 접속하면 항상 만료된 것으로 처리되기 때문이다", "이름으로 발급된 인증서의 이름 목록에 IP 가 없기 때문이다", "IP 로 접속하면 서버가 인증서를 보내지 않기 때문이다", "IP 접속은 암호화가 지원되지 않기 때문이다"]', 1, '브라우저와 curl 은 접속한 호스트(이름 또는 IP)가 인증서의 SAN 목록에 있는지 확인합니다. 보통 도메인 이름으로 발급되므로 IP 로 접속하면 목록에 없어 불일치가 납니다. 암호화와 인증서 전달은 IP 로도 정상 동작합니다. (IP 항목이 들어 있는 인증서도 있지만, 이 서버의 인증서에는 없는 경우입니다.)', NULL, NULL, NULL, NULL
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 576 AND order_index = 8);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 576, 9, 'DNS 를 거치지 않고 주소 지정', '아직 DNS 에 반영되지 않은 새 서버(192.0.2.50)를 도메인 이름 그대로 테스트하려 합니다. 이름은 유지하되 **이 주소로 연결하게 하는** curl 옵션을 채우세요. (SNI·Host 헤더·인증서 검증이 도메인 이름 기준으로 유지됩니다)', '`curl --help` 에서 호스트와 포트에 대한 주소를 미리 정해 주는 옵션을 찾아 보세요.', NULL, NULL, '[]', 'fill', '["resolve", "header", "cacert", "data"]', NULL, '`--resolve 호스트:포트:주소` 는 그 이름의 DNS 결과를 지정한 주소로 대신합니다. URL 은 이름 그대로라 SNI·Host 헤더·인증서 이름 검증이 정상 동작합니다. `--header` 는 헤더 추가, `--cacert` 는 CA 파일 지정, `--data` 는 요청 본문 전송입니다.', '[0]', 'curl --{0} api.example.com:443:192.0.2.50 https://api.example.com/', NULL, NULL
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 576 AND order_index = 9);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 576, 10, '502 장애 점검 순서', '웹 서비스가 502 를 돌려줍니다. 사용자에게 보이는 쪽에서 시작해 원인이 있는 쪽으로 좁혀 가려 합니다. 올바른 순서로 놓으세요. 업스트림에 직접 접속해 증상을 재현하는 것이 프로세스 상태를 확인하는 것보다 앞섭니다.', '사용자에게 가까운 쪽부터 원인 쪽으로 좁혀 가는 순서입니다.', NULL, NULL, '[]', 'order', '["업스트림 서버에 직접 `curl` 로 접속해 본다", "프록시의 에러 로그에서 업스트림 오류를 찾는다", "업스트림 프로세스가 떠 있고 포트가 LISTEN 인지 확인한다", "`curl -v` 로 응답 상태와 헤더를 확인한다"]', NULL, '응답을 먼저 확인하고, 프록시 에러 로그로 어떤 오류(연결 거부·시간 초과)인지 보고, 업스트림에 직접 접속해 재현한 뒤, 마지막으로 프로세스와 포트 상태를 확인합니다.', '[3, 1, 0, 2]', NULL, NULL, NULL
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 576 AND order_index = 10);
